  a1: "Жиндирго апараталда. OpenAmer разговорал, файлал ва конфигурация локалиябго хъвай гьабула. Централияб база гьечІо ва лъабабилеб рахъалде кьей гьечІо, жинца облакалъулав провайдер хІалтІизабизе кколагониги.",
  q2: "Дир гьунар бугеб компьютер къваригІула?",
  a2: "Кумекалъуласдаго гьечІо. Локалиял моделаздалъун 16 GB RAM-алдаса цІикІкІун бугеб заманалъулав CPU рекомендация гьабула; GPU-гун хІатІиде хІалтІула.",
  q3: "OpenAmer кІичІого бугеб?",
  a3: "OpenAmer открытияб код буго. Лицензиялъулаб харж гьечІо. ГІемералъул харж гьабизе ккола облакалъулал моделаздаго.",
  q4: "Жиндирго гьарурал функцияби тІаде жубазе бегьула?",
  a4: "Бегьула. Скиллаздалъун такрарлъулал хІалтІаби модулаздалъун бихьизабизе бегьула. Хъван хадуб, щибаб сессиялда рекъон буго.",
  q5: "OpenAmer доктор яги юрист хІисабалда хІалтІула?",
  a5: "ГьечІо. OpenAmer цІехей, структура ва хъвай гьабизе кумек гьабула — амма профессионалияб маслигІат хІисабалда хІалтІуларо.",
  q6: "Кинаб куцалда байбихьизе?",
  a6: "GitHub-алда документация цІализе. Windows, macOS, Linux ва Android-алъе лъезе шагалал ратала.",
  cta_title: "ЦІияб заманалъе хІадур?",
  cta_sub: "OpenAmer лъезе ва жиндирго заман кьун хІалтІи тІаде кьезе.",
  cta_b1: "ГьабсагІат лъезе",
  cta_b2: "Видео бихьизе",
  foot_desc: "Жиндирго AI кумекалъулав. Локалияб, хІалбихьи гьечІо ва хІакъикъияб — Швейцариялда гьабураб.",
