  q1: "আমার ডেটা কোথায় থাকে?",
  a1: "আপনার ডিভাইসে। OpenAmer কথোপকথন, ফাইল এবং কনফিগারেশন স্থানীয়ভাবে সংরক্ষণ করে। কোনো কেন্দ্রীয় ডেটাবেস নেই এবং তৃতীয় পক্ষের কাছে কোনো স্থানান্তর নেই যদি না আপনি ইচ্ছাকৃতভাবে একটি ক্লাউড প্রদানকারী ব্যবহার করেন।",
