  faq_title: "ಪದೇ ಪದೇ ಕೇಳಲಾಗುವ ಪ್ರಶ್ನೆಗಳು",
  q1: "ನನ್ನ ಡೇಟಾ ಎಲ್ಲಿದೆ?",
  a1: "ನಿಮ್ಮ ಸಾಧನದಲ್ಲಿ. OpenAmer ಸಂಭಾಷಣೆಗಳು, ಫೈಲ್‌ಗಳು ಮತ್ತು ಸಂರಚನೆಯನ್ನು ಸ್ಥಳೀಯವಾಗಿ ಸಂಗ್ರಹಿಸುತ್ತದೆ. ಕೇಂದ್ರೀಯ ಡೇಟಾಬೇಸ್ ಇಲ್ಲ ಮತ್ತು ನೀವು ಉದ್ದೇಶಪೂರ್ವಕವಾಗಿ ಕ್ಲೌಡ್ ಪ್ರೊವೈಡರ್ ಬಳಸದ ಹೊರತು ಮೂರನೇ ಪಕ್ಷಗಳಿಗೆ ವರ್ಗಾವಣೆ ಇಲ್ಲ.",
  q2: "ನನಗೆ ಶಕ್ತಿಶಾಲಿ ಕಂಪ್ಯೂಟರ್ ಬೇಕೇ?",
  a2: "ಸಹಾಯಕಕ್ಕೆ ಸ್ವತಃ ಅಲ್ಲ. ಸ್ಥಳೀಯ ಮಾದರಿಗಳಿಗೆ ಕನಿಷ್ಠ 16 GB RAM ಇರುವ ಆಧುನಿಕ CPU ಶಿಫಾರಸು ಮಾಡಲಾಗುತ್ತದೆ; GPU ಇದ್ದರೆ ಅದು ಬಹಳ ವೇಗವಾಗಿ ಚಲಿಸುತ್ತದೆ.",
  q3: "OpenAmer ಉಚಿತವೇ?",
  a3: "OpenAmer ಮುಕ್ತ ಮೂಲವಾಗಿದೆ. ಪರವಾನಗಿ ವೆಚ್ಚಗಳಿಲ್ಲ. ಕ್ಲೌಡ್ ಮಾದರಿಗಳಿಗೆ ಮಾತ್ರ ಬಳಕೆ ಆಧಾರಿತ ವೆಚ್ಚಗಳು ಉಂಟಾಗುತ್ತವೆ.",
  q4: "ನನ್ನ ಸ್ವಂತ ಸಾಮರ್ಥ್ಯಗಳನ್ನು ಸೇರಿಸಬಹುದೇ?",
  a4: "ಹೌದು. ಕೌಶಲ್ಯಗಳು ಪುನರಾವರ್ತಿತ ಕಾರ್ಯಪ್ರವಾಹಗಳನ್ನು ಮಾಡ್ಯೂಲ್‌ಗಳಾಗಿ ವ್ಯಾಖ್ಯಾನಿಸಲು ಅನುಮತಿಸುತ್ತವೆ. ಒಮ್ಮೆ ಬರೆದ ನಂತರ, ಅವು ಪ್ರತಿ ಸೆಷನ್‌ನಲ್ಲಿಯೂ ಲಭ್ಯವಿರುತ್ತವೆ.",
  q5: "OpenAmer ವೈದ್ಯರು ಅಥವಾ ವಕೀಲರನ್ನು ಬದಲಿಸುತ್ತದೆಯೇ?",
  a5: "ಇಲ್ಲ. OpenAmer ಸಂಶೋಧನೆ, ರಚನೆ ಮತ್ತು ಪದಗಳನ್ನು ಬೆಂಬಲಿಸುತ್ತದೆ — ಆದರೆ ವೃತ್ತಿಪರ ಸಲಹೆಯನ್ನು ಬದಲಿಸುವುದಿಲ್ಲ.",
  q6: "ನಾನು ಹೇಗೆ ಪ್ರಾರಂಭಿಸಬೇಕು?",
  a6: "GitHub ನಲ್ಲಿರುವ ದಾಖಲೆಗಳನ್ನು ಅನುಸರಿಸಿ. Windows, macOS, Linux ಮತ್ತು Android ಗಾಗಿ ಸ್ಥಾಪನಾ ಹಂತಗಳನ್ನು ನೀವು ಕಾಣುತ್ತೀರಿ.",
  cta_title: "ಹೊಸ ಯುಗಕ್ಕೆ ಸಿದ್ಧರೇ?",
  cta_sub: "OpenAmer ಅನ್ನು ಸ್ಥಾಪಿಸಿ ಮತ್ತು ನಿಮ್ಮ ಸಮಯವನ್ನು ಕದಿಯುವ ಕೆಲಸವನ್ನು ವಹಿಸಿಕೊಡಿ.",
  cta_b1: "ಈಗ ಸ್ಥಾಪಿಸಿ",
  cta_b2: "ವೀಡಿಯೊ ನೋಡಿ",
  foot_desc: "ನಿಮ್ಮ ವೈಯಕ್ತಿಕ AI ಸಹಾಯಕ. ಸ್ಥಳೀಯ, ಖಾಸಗಿ ಮತ್ತು ಪ್ರಾಮಾಣಿಕ — ಸ್ವಿಟ್ಜರ್ಲೆಂಡ್‌ನಲ್ಲಿ ನಿರ್ಮಿಸಲಾಗಿದೆ.",
  foot_product: "ಉತ್ಪನ್ನ",
  foot_res: "ಸಂಪನ್ಮೂಲಗಳು",
  foot_legal: "ಕಾನೂನು",
