  a1: "ເທິງອຸປະກອນຂອງທ່ານ. OpenAmer ເກັບການສົນທະນາ, ໄຟລ໌ ແລະ ການຕັ້ງຄ່າໄວ້ໃນເຄື່ອງ. ບໍ່ມີຖານຂໍ້ມູນສູນກາງ ແລະ ບໍ່ມີການສົ່ງຕໍ່ໃຫ້ບຸກຄົນທີສາມ ເວັ້ນແຕ່ທ່ານເລືອກໃຊ້ຜູ້ໃຫ້ບໍລິການຄລາວໂດຍເຈດຕະນາ.",
