  q6: "ຂ້ອຍເລີ່ມຢ່າງໃດ?",
  a6: "ຕິດຕາມເອກະສານເທິງ GitHub. ທ່ານຈະພົບຂັ້ນຕອນການຕິດຕັ້ງສຳລັບ Windows, macOS, Linux ແລະ Android.",
