  f4d: "നിങ്ങളുടെ സ്വന്തം കഴിവുകൾ മൊഡ്യൂളുകളായി: ആവർത്തിച്ചുള്ള വർക്ക്ഫ്ലോകൾ സ്ഥിരമായ അറിവായി മാറുന്നു.",
  f5t: "ബഹുഭാഷ",
  f5d: "നിങ്ങളുടെ ഭാഷയിൽ മനസ്സിലാക്കി ഉത്തരം നൽകുന്നു — വീട്ടിൽ, ജോലിയിൽ, നിങ്ങളുടെ പ്രോജക്ടിൽ.",
  f6t: "വേഗതയേറിയതും ഭാരം കുറഞ്ഞതും",
  f6d: "സെക്കൻഡുകൾക്കുള്ളിൽ ആരംഭിക്കുന്നു, സമർപ്പിത GPU ഇല്ലാത്ത ലാപ്ടോപ്പുകളിൽ പ്രവർത്തിക്കുന്നു. ക്ലൗഡിനെ ആശ്രയിക്കുന്നില്ല.",
  how_eyebrow: "മൂന്ന് ഘട്ടങ്ങൾ",
