  how_sub: "ഇൻസ്റ്റാൾ ചെയ്യുക, ബന്ധിപ്പിക്കുക, ഏൽപ്പിക്കുക. അത്രമാത്രം.",
  s1t: "ഇൻസ്റ്റാൾ",
  s1d: "നിങ്ങളുടെ മെഷീനിൽ OpenAmer സജ്ജീകരിക്കുക — Windows, macOS, Linux അല്ലെങ്കിൽ Android. സെർവറുകൾ ഇല്ല, സബ്സ്ക്രിപ്ഷൻ ഇല്ല.",
  s2t: "ബന്ധിപ്പിക്കുക",
  s2d: "നിങ്ങളുടെ പ്രോഗ്രാമുകൾ, ഫയലുകൾ, അക്കൗണ്ടുകൾ ലിങ്ക് ചെയ്യുക. അസിസ്റ്റന്റ് എന്ത് കാണണമെന്ന് നിങ്ങൾ തീരുമാനിക്കുന്നു.",
  s3t: "ഏൽപ്പിക്കുക",
  s3d: "ജോലികൾ നൽകി പ്രവർത്തിക്കാൻ അനുവദിക്കുക: ഗവേഷണം, രേഖകൾ, ഓട്ടോമേഷൻ, ഓർഗനൈസേഷൻ.",
  v_eyebrow: "വീഡിയോ",
  v_title: "60 സെക്കൻഡിൽ OpenAmer",
  v_sub: "പുതിയ യുഗത്തിന്റെ അർത്ഥം കാണുക.",
  u_eyebrow: "ഉപയോഗ കേസുകൾ",
  u_title: "സമയം തിരികെ ലഭിക്കാൻ ആഗ്രഹിക്കുന്നവർക്ക്",
  u_sub: "ജോലി, പഠനം അല്ലെങ്കിൽ ദൈനംദിന ജീവിതം — ആരും ഇഷ്ടപ്പെടാത്ത ജോലി OpenAmer ഏറ്റെടുക്കുന്നു.",
  u1t: "ജോലി & ഓഫീസ്",
  u1d: "ക്വോട്ടുകൾ, റിപ്പോർട്ടുകൾ, ഇമെയിലുകൾ, ഗവേഷണം — മണിക്കൂറുകൾക്ക് പകരം മിനിറ്റുകളിൽ, സ്ഥിരതയോടെയും നന്നായി എഴുതിയതും.",
  u2t: "പഠനം & പഠനം",
  u2d: "സംഗ്രഹങ്ങൾ, പഠന പ്ലാനുകൾ, സ്രോതസ്സ് ജോലി. പകർത്തല്ല, മനസ്സിലാക്കുക.",
  u3t: "വികസനം",
  u3d: "കോഡ് എഴുതുക, അവലോകനം ചെയ്യുക, ഡോക്യുമെന്റ് ചെയ്യുക. ടെസ്റ്റുകൾ പ്രവർത്തിപ്പിച്ച് ബഗുകൾ ക്രമബദ്ധമായി വേർതിരിക്കുക.",
  u4t: "ദൈനംദിനം & ഓർഗനൈസേഷൻ",
  u4d: "അപ്പോയിന്റ്മെന്റുകൾ, അധികാരികൾ, കരാറുകൾ, മീറ്റിംഗ് തയ്യാറെടുപ്പ് — ഇനി ഒന്നും മറക്കരുത്.",
  faq_eyebrow: "പതിവ് ചോദ്യങ്ങൾ",
  faq_title: "പതിവായി ചോദിക്കുന്ന ചോദ്യങ്ങൾ",
  q1: "എന്റെ ഡാറ്റ എവിടെയാണ്?",
  a1: "നിങ്ങളുടെ ഉപകരണത്തിൽ. OpenAmer സംഭാഷണങ്ങൾ, ഫയലുകൾ, കോൺഫിഗറേഷൻ ലോക്കലായി സംഭരിക്കുന്നു. കേന്ദ്ര ഡാറ്റാബേസ് ഇല്ല, നിങ്ങൾ ബോധപൂർവ്വം ഒരു ക്ലൗഡ് പ്രൊവൈഡർ ഉപയോഗിക്കുന്നില്ലെങ്കിൽ തേർഡ് പാർട്ടികൾക്ക് കൈമാറ്റവുമില്ല.",
  q2: "എനിക്ക് ശക്തമായ കമ്പ്യൂട്ടർ വേണോ?",
  a2: "അസിസ്റ്റന്റിന് തന്നെ വേണ്ട. ലോക്കൽ മോഡലുകൾക്ക് കുറഞ്ഞത് 16 GB RAM ഉള്ള ആധുനിക CPU ശുപാർശ ചെയ്യുന്നു; GPU ഉണ്ടെങ്കിൽ വളരെ വേഗത്തിൽ പ്രവർത്തിക്കും.",
  q3: "OpenAmer സൗജന്യമാണോ?",
  a3: "OpenAmer ഓപ്പൺ സോഴ്സ് ആണ്. ലൈസൻസ് ചെലവുകൾ ഇല്ല. ക്ലൗഡ് മോഡലുകൾക്ക് മാത്രം ഉപയോഗ അടിസ്ഥാനത്തിലുള്ള ചെലവുകൾ വരും.",
  q4: "എനിക്ക് എന്റെ സ്വന്തം കഴിവുകൾ ചേർക്കാമോ?",
  a4: "അതെ. സ്കിൽസ് ഉപയോഗിച്ച് ആവർത്തിച്ചുള്ള വർക്ക്ഫ്ലോകൾ മൊഡ്യൂളുകളായി നിർവചിക്കാം. ഒരിക്കൽ എഴുതിയാൽ, എല്ലാ സെഷനിലും ലഭ്യമാകും.",
  q5: "OpenAmer ഒരു ഡോക്ടറെയോ അഭിഭാഷകനെയോ മാറ്റിസ്ഥാപിക്കുമോ?",
  a5: "ഇല്ല. OpenAmer ഗവേഷണം, ഘടന, രൂപീകരണം എന്നിവയെ പിന്തുണയ്ക്കുന്നു — പക്ഷേ പ്രൊഫഷണൽ ഉപദേശം മാറ്റിസ്ഥാപിക്കുന്നില്ല.",
  q6: "ഞാൻ എങ്ങനെ ആരംഭിക്കും?",
  a6: "GitHub-ലെ ഡോക്യുമെന്റേഷൻ പിന്തുടരുക. Windows, macOS, Linux, Android എന്നിവയ്ക്കുള്ള ഇൻസ്റ്റലേഷൻ ഘട്ടങ്ങൾ അവിടെ കാണാം.",
