  foot_desc: "നിങ്ങളുടെ വ്യക്തിഗത AI അസിസ്റ്റന്റ്. ലോക്കൽ, സ്വകാര്യം, സത്യസന്ധം — സ്വിറ്റ്സർലൻഡിൽ നിർമ്മിച്ചത്.",
