  u1d: "कोटेशन, प्रतिवेदन, इमेल र अनुसन्धान घण्टाको सट्टा मिनेटमा — सुसंगत र राम्रोसँग लेखिएको।",
  u2t: "अध्ययन र सिकाइ",
  u2d: "सारांश, अध्ययन योजना, स्रोत कार्य। प्रतिलिपि नगरी बुझ्नुहोस्।",
  u3t: "विकास",
  u3d: "कोड लेख्नुहोस्, समीक्षा गर्नुहोस् र कागजात बनाउनुहोस्। परीक्षणहरू चलाउनुहोस् र बगहरू व्यवस्थित रूपमा अलग गर्नुहोस्।",
  u4t: "दैनिक जीवन र संगठन",
  u4d: "अपोइन्टमेन्ट, अधिकारीहरू, सम्झौताहरू, बैठक तयारी — फेरि कहिल्यै केही बिर्सनुहुन्न।",
  faq_eyebrow: "प्रश्नोत्तर",
  faq_title: "बारम्बार सोधिने प्रश्नहरू",
  q1: "मेरो डाटा कहाँ रहन्छ?",
  a1: "तपाईंको यन्त्रमा। OpenAmer ले कुराकानी, फाइल र कन्फिगरेसन स्थानीय रूपमा भण्डारण गर्छ। कुनै केन्द्रीय डाटाबेस छैन र तपाईंले जानाजानी क्लाउड प्रदायक प्रयोग नगरेसम्म तेस्रो पक्षमा स्थानान्तरण हुँदैन।",
  q2: "मलाई शक्तिशाली कम्प्युटर चाहिन्छ?",
  a2: "सहायक आफैको लागि चाहिँदैन। स्थानीय मोडेलहरूका लागि कम्तीमा १६ GB RAM भएको आधुनिक CPU सिफारिस गरिन्छ; GPU भएमा यो धेरै छिटो चल्छ।",
  q3: "OpenAmer निःशुल्क छ?",
  a3: "OpenAmer खुला स्रोत हो। कुनै इजाजतपत्र लागत छैन। केवल क्लाउड मोडेलहरूमा प्रयोग-आधारित लागत लाग्छ।",
  q4: "मैले आफ्नै क्षमताहरू थप्न सक्छु?",
  a4: "हो। सीपहरूले तपाईंलाई आवर्ती कार्यप्रवाहहरू मोड्युलको रूपमा परिभाषित गर्न दिन्छ। एक पटक लेखिसकेपछि, तिनीहरू प्रत्येक सत्रमा उपलब्ध हुन्छन्।",
  q5: "OpenAmer ले डाक्टर वा वकिललाई प्रतिस्थापन गर्छ?",
  a5: "होइन। OpenAmer ले अनुसन्धान, संरचना र शब्दावलीमा सहयोग गर्छ — तर व्यावसायिक सल्लाहलाई प्रतिस्थापन गर्दैन।",
  q6: "म कसरी सुरु गर्ने?",
  a6: "GitHub मा कागजात पालना गर्नुहोस्। तपाईंले Windows, macOS, Linux र Android का लागि स्थापना चरणहरू पाउनुहुनेछ।",
  cta_title: "नयाँ युगको लागि तयार हुनुहुन्छ?",
  cta_sub: "OpenAmer स्थापना गर्नुहोस् र तपाईंको समय चोर्ने काम हस्तान्तरण गर्नुहोस्।",
  cta_b1: "अहिले स्थापना गर्नुहोस्",
  cta_b2: "भिडियो हेर्नुहोस्",
  foot_desc: "तपाईंको व्यक्तिगत AI सहायक। स्थानीय, निजी र इमानदार — स्विट्जरल्याण्डमा निर्मित।",
  foot_product: "उत्पादन",
  foot_res: "स्रोतहरू",
  foot_legal: "कानूनी",
