  s3d: "කාර්යයන් පවරා ඒවා ක්‍රියාත්මක වීමට ඉඩ දෙන්න: පර්යේෂණ, ලේඛන, ස්වයංක්‍රීයකරණය, සංවිධානය.",
  v_eyebrow: "වීඩියෝ",
  v_title: "තත්පර 60කින් OpenAmer",
  v_sub: "නව යුගය යන්නෙන් අදහස් වන්නේ කුමක්දැයි බලන්න.",
  u_eyebrow: "භාවිත අවස්ථා",
  u_title: "තමන්ගේ කාලය ආපසු ලබා ගැනීමට අවශ්‍ය අය සඳහා",
  u_sub: "රැකියාව, අධ්‍යයනය හෝ දෛනික ජීවිතය — කිසිවෙකු නොසතුටු වන වැඩ OpenAmer භාර ගනී.",
  u1t: "රැකියාව සහ කාර්යාලය",
  u1d: "පැය ගණනක් වෙනුවට විනාඩි කිහිපයකින් මිල ගණන්, වාර්තා, ඊමේල් සහ පර්යේෂණ — ස්ථාවර සහ හොඳින් ලියා ඇති.",
  u2t: "අධ්‍යයනය සහ ඉගෙනීම",
  u2d: "සාරාංශ, අධ්‍යයන සැලසුම්, මූලාශ්‍ර කටයුතු. පිටපත් කරනවා වෙනුවට තේරුම් ගන්න.",
  u3t: "සංවර්ධනය",
  u3d: "කේත ලියන්න, සමාලෝචනය කරන්න සහ ලේඛනගත කරන්න. පරීක්ෂණ ධාවනය කර දෝෂ ක්‍රමානුකූලව හුදකලා කරන්න.",
  u4t: "දෛනික ජීවිතය සහ සංවිධානය",
  u4d: "හමුවීම්, බලධාරීන්, ගිවිසුම්, රැස්වීම් සූදානම — නැවත කිසිවක් අමතක නොකරන්න.",
  faq_eyebrow: "නිතර අසන ප්‍රශ්න",
  faq_title: "නිතර අසන ප්‍රශ්න",
  q1: "මගේ දත්ත රැඳී ඇත්තේ කොහේද?",
  a1: "ඔබේ උපාංගයේ. OpenAmer සංවාද, ගොනු සහ වින්‍යාසය දේශීයව ගබඩා කරයි. මධ්‍යම දත්ත සමුදායක් නැති අතර ඔබ හිතාමතා ක්ලවුඩ් සැපයුම්කරුවෙකු භාවිත නොකරන්නේ නම් තෙවන පාර්ශවයන්ට මාරු කිරීමක් නැත.",
  q2: "මට බලවත් පරිගණකයක් අවශ්‍යද?",
  a2: "සහායකයාටම අවශ්‍ය නැත. දේශීය මාදිලි සඳහා අවම වශයෙන් 16 GB RAM සහිත නවීන CPU එකක් නිර්දේශ කෙරේ; GPU එකක් සමඟ එය වඩාත් වේගයෙන් ක්‍රියාත්මක වේ.",
  q3: "OpenAmer නොමිලේද?",
  a3: "OpenAmer විවෘත මූලාශ්‍රයකි. බලපත්‍ර වියදම් නැත. ක්ලවුඩ් මාදිලි සඳහා පමණක් භාවිතය මත පදනම් වූ වියදම් ඇත.",
  q4: "මට මගේම හැකියාවන් එකතු කළ හැකද?",
  a4: "ඔව්. කුසලතා මගින් පුනරාවර්තන කාර්ය ප්‍රවාහ මොඩියුල ලෙස අර්ථ දැක්විය හැක. ලියූ පසු ඒවා සෑම සැසියකම ලබා ගත හැක.",
  q5: "OpenAmer වෛද්‍යවරයෙකු හෝ නීතිඥයෙකු ආදේශ කරයිද?",
  a5: "නැත. OpenAmer පර්යේෂණ, ව්‍යුහය සහ වචන රචනයට සහාය වේ — නමුත් වෘත්තීය උපදෙස් ආදේශ නොකරයි.",
  q6: "මම ආරම්භ කරන්නේ කෙසේද?",
  a6: "GitHub හි ලේඛන අනුගමනය කරන්න. Windows, macOS, Linux සහ Android සඳහා ස්ථාපන පියවර ඔබට හමුවේ.",
