  f2t: "Lisebelisoa tse fetang 120",
  f2d: "Terminal, ho iketsetsa sebatli, taolo ea lifaele, imeile, khalendara, li-database — li hokahane ntle le bothata.",
  f3t: "E sebetsa ka boikemelo",
  f3d: "E etsa lipatlisiso, e ngola, e iketsetsa 'me e phetha mesebetsi ea mehato e mengata — ntle le hore u e laele mohato o mong le o mong.",
  f4t: "E atolosoa ka litsebo",
  f4d: "Bokhoni ba hau e le li-module: mekhoa ea mosebetsi e iphetang e fetoha tsebo e sa feleng.",
  f5t: "Lipuo tse ngata",
  f5d: "E utloisisa 'me e araba ka puo ea hau — hae, mosebetsing, morerong oa hau.",
  f6t: "E potlakile 'me e bobebe",
  f6d: "E qala ka metsotsoana, e sebetsa ho li-laptop tse se nang GPU e ikhethileng. Ha e itšetlehe ka leru.",
  how_eyebrow: "Mehato e meraro",
  how_title: "E loketse ka metsotso",
  how_sub: "Kenya, hokahanya, abela. Ke sona feela se hlokahalang.",
  s1t: "Kenya",
  s1d: "Beha OpenAmer mochining oa hau — Windows, macOS, Linux kapa Android. Ha ho li-server, ha ho peeletso.",
  s2t: "Hokahanya",
  s2d: "Hokahanya mananeo a hau, lifaele le liak'haonte. Ke uena ea etsang qeto ea hore na mothusi a bone eng.",
  s3t: "Abela",
  s3d: "Aba mesebetsi 'me u e tlohele e sebetse: lipatlisiso, litokomane, ho iketsetsa, tlhophiso.",
  v_eyebrow: "Video",
  v_title: "OpenAmer ka metsotsoana e 60",
  v_sub: "Bona hore na mehla e mecha e bolelang.",
  u_eyebrow: "Lisebelisoa",
  u_title: "Bakeng sa batho ba batlang nako ea bona morao",
  u_sub: "Mosebetsi, thuto kapa bophelo ba letsatsi le letsatsi — OpenAmer e nka mosebetsi oo ho seng motho ea o ratang.",
  u1t: "Mosebetsi le ofisi",
  u1d: "Likhoutu, litlaleho, li-imeile le lipatlisiso ka metsotso ho e-na le lihora — li tsitsitse 'me li ngotsoe hantle.",
  u2t: "Thuto le ho ithuta",
  u2d: "Likakaretso, meralo ea ho ithuta, mosebetsi oa mehloli. Utloisisa ho e-na le ho kopitsa.",
  u3t: "Nts'etsopele",
  u3d: "Ngola, hlahloba le ho ngola litokomane tsa khoutu. Matha liteko 'me u khetholle liphoso ka mokhoa o hlophisitsoeng.",
  u4t: "Letsatsi le letsatsi le tlhophiso",
  u4d: "Likopano, balaoli, likonteraka, litokisetso tsa liboka — u se ke ua hlola u lebala letho.",
  faq_eyebrow: "Lipotso tse botsoang hangata",
  faq_title: "Lipotso tse botsoang hangata",
  q1: "Data ea ka e lula hokae?",
  a1: "Sesebelisoeng sa hau. OpenAmer e boloka lipuisano, lifaele le tlhophiso sebakeng sa heno. Ha ho database e bohareng ebile ha ho phetisetso ho batho ba bang ntle le haeba u sebelisa mofani oa leru ka boomo.",
  q2: "Na ke hloka khomphutha e matla?",
  a2: "Eseng bakeng sa mothusi ka boeona. Bakeng sa mefuta ea sebaka, ho khothaletsoa CPU ea sejoale-joale e nang le bonyane 16 GB RAM; ka GPU e sebetsa kapele haholo.",
  q3: "Na OpenAmer e mahala?",
  a3: "OpenAmer e na le mohloli o bulehileng. Ha ho litšenyehelo tsa laesense. Ke mefuta ea leru feela e nang le litšenyehelo tse ipapisitseng le tšebeliso.",
  q4: "Na nka eketsa bokhoni ba ka?",
  a4: "Ee. Litsebo li u lumella ho hlalosa mekhoa ea mosebetsi e iphetang e le li-module. Hang ha li ngotsoe, li fumaneha sebokeng se seng le se seng.",
  q5: "Na OpenAmer e nka sebaka sa ngaka kapa 'molao?",
  a5: "Che. OpenAmer e tšehetsa lipatlisiso, sebopeho le mantsoe — empa ha e nke sebaka sa keletso ea setsebi.",
  q6: "Nka qala joang?",
  a6: "Latela litokomane ho GitHub. U tla fumana mehato ea ho kenya bakeng sa Windows, macOS, Linux le Android.",
  cta_title: "U loketse mehla e mecha?",
  cta_sub: "Kenya OpenAmer 'me u fane ka mosebetsi o u utsoetsang nako.",
  cta_b1: "Kenya hona joale",
  cta_b2: "Shebella video",
  foot_desc: "Mothusi oa hau oa AI. Oa sebaka, oa lekunutu le oa 'nete — o hahiloe Switzerland.",
  foot_product: "Sehlahisoa",
  foot_res: "Lisebelisoa",
  foot_legal: "Molao",
