  s1t: "நிறுவு",
  s1d: "OpenAmer-ஐ உங்கள் கணினியில் அமைக்கவும் — Windows, macOS, Linux அல்லது Android. சேவையகங்கள் இல்லை, சந்தா இல்லை.",
