  s2d: "உங்கள் நிரல்கள், கோப்புகள் மற்றும் கணக்குகளை இணைக்கவும். உதவியாளர் எதைப் பார்க்கலாம் என்பதை நீங்கள் தீர்மானிக்கிறீர்கள்.",
