  u3d: "కోడ్ రాయండి, సమీక్షించండి మరియు డాక్యుమెంట్ చేయండి. పరీక్షలు నడపండి మరియు బగ్‌లను క్రమపద్ధతిలో వేరుచేయండి.",
  u4t: "రోజువారీ & నిర్వహణ",
  u4d: "అపాయింట్‌మెంట్లు, అధికారులు, ఒప్పందాలు, సమావేశ సన్నాహం — ఇక ఏదీ మర్చిపోకండి.",
  faq_eyebrow: "తరచుగా అడిగే ప్రశ్నలు",
  faq_title: "తరచుగా అడిగే ప్రశ్నలు",
  q1: "నా డేటా ఎక్కడ ఉంటుంది?",
  a1: "మీ పరికరంలో. OpenAmer సంభాషణలు, ఫైల్స్ మరియు కాన్ఫిగరేషన్‌ను స్థానికంగా నిల్వ చేస్తుంది. కేంద్ర డేటాబేస్ లేదు మరియు మీరు ఉద్దేశపూర్వకంగా క్లౌడ్ ప్రొవైడర్‌ను ఉపయోగించనంత వరకు మూడవ పక్షాలకు బదిలీ లేదు.",
  q2: "నాకు శక్తివంతమైన కంప్యూటర్ అవసరమా?",
  a2: "సహాయకుడికి అవసరం లేదు. స్థానిక మోడల్‌ల కోసం కనీసం 16 GB RAM ఉన్న ఆధునిక CPU సిఫార్సు చేయబడుతుంది; GPU ఉంటే చాలా వేగంగా నడుస్తుంది.",
  q3: "OpenAmer ఉచితమా?",
  a3: "OpenAmer ఓపెన్ సోర్స్. లైసెన్స్ ఖర్చులు లేవు. క్లౌడ్ మోడల్‌లకు మాత్రమే వినియోగ ఆధారిత ఖర్చులు ఉంటాయి.",
  q4: "నా స్వంత సామర్థ్యాలను జోడించవచ్చా?",
  a4: "అవును. స్కిల్స్ ద్వారా పునరావృత వర్క్‌ఫ్లోలను మాడ్యూల్స్‌గా నిర్వచించవచ్చు. ఒకసారి రాసిన తర్వాత, అవి ప్రతి సెషన్‌లో అందుబాటులో ఉంటాయి.",
  q5: "OpenAmer వైద్యుడు లేదా న్యాయవాదిని భర్తీ చేస్తుందా?",
  a5: "లేదు. OpenAmer పరిశోధన, నిర్మాణం మరియు పదాలను మద్దతు ఇస్తుంది — కానీ వృత్తిపరమైన సలహాను భర్తీ చేయదు.",
  q6: "నేను ఎలా ప్రారంభించాలి?",
  a6: "GitHub లోని డాక్యుమెంటేషన్‌ను అనుసరించండి. Windows, macOS, Linux మరియు Android కోసం ఇన్‌స్టాలేషన్ దశలు మీకు అక్కడ లభిస్తాయి.",
  cta_title: "కొత్త యుగానికి సిద్ధమా?",
  cta_sub: "OpenAmer ను ఇన్‌స్టాల్ చేసి మీ సమయాన్ని దొంగిలించే పనిని అప్పగించండి.",
  cta_b1: "ఇప్పుడే ఇన్‌స్టాల్ చేయండి",
  cta_b2: "వీడియో చూడండి",
  foot_desc: "మీ వ్యక్తిగత AI సహాయకుడు. స్థానికం, ప్రైవేట్ మరియు నిజాయితీ — స్విట్జర్లాండ్‌లో నిర్మించబడింది.",
  foot_product: "ఉత్పత్తి",
