  q1: "ዳታይ ኣበይ ይነብር?",
  a1: "ኣብ መሳርሒኻ። OpenAmer ዕላላታት፣ ፋይላትን ምስንዳእን ብኣካል ይዕቅብ። ማእከላይ ዳታቤዝ የለን፣ ንሳልሳይ ወገን ምስግጋር የለን እንተዘይኮነ ብፍቓድካ ክላውድ ኣቕራቢ ትጥቀም።",
