  f1d: "Tsotlhe di dira mo sedirisiweng sa gago. Ga go telemetry, ga go di-server tsa batho ba bangwe, ga go dikgoloso tse di fitlhilweng.",
  f2t: "Didirisiwa tse di fetang 120",
  f2d: "Therminolo, boiketsi jwa sebatli, taolo ya difaele, imeile, khalendara, dathabeisi — di golagantswe ntle le mathata.",
  f3t: "E itira ka boeona",
  f3d: "E batlisisa, e kwala, e itirisa le go wetsa ditiro tsa dikgato tse dintsi — ntle le gore o laele kgato nngwe le nngwe.",
  f4t: "E atolosiwa ka dikgono",
  f4d: "Bokgoni jwa gago e le dimojule: ditsamaiso tse di boelediwang di nna kitso ya ruri.",
  f5t: "Dipuo tse dintsi",
  f5d: "E tlhaloganya e bile e araba ka puo ya gago — kwa gae, kwa tirong, mo porojekeng ya gago.",
  f6t: "E lebelo & e bobebe",
  f6d: "E simolola ka metsotswana, e dira mo dikhomputareng tse di se nang GPU e e kgethegileng. Ga go ikaegile ka leru.",
  how_eyebrow: "Dikgato tse tharo",
  how_title: "E ipaakanyeditse ka metsotso",
  how_sub: "Tsenya, golaganya, abela. Ke gona fela.",
  s1t: "Tsenya",
  s1d: "Baya OpenAmer mo motšineng wa gago — Windows, macOS, Linux kgotsa Android. Ga go di-server, ga go pego ya kgwedi.",
  s2t: "Golaganya",
  s2d: "Golaganya mananeo a gago, difaele le diakhaonto. O swetsa gore motlhankedi a bone eng.",
  s3t: "Abela",
  s3d: "Neela ditiro mme o di tlogele di tsamaya: patlisiso, dikwalo, boiketsi, thulaganyo.",
  v_eyebrow: "Bidiyo",
  v_title: "OpenAmer ka metsotswana e le 60",
  v_sub: "Bona gore motlha o mosha o kaya eng.",
  u_eyebrow: "Dikgetsi tsa tiriso",
  u_title: "Bakeng sa batho ba ba batlang nako ya bone morago",
  u_sub: "Tiro, thuto kgotsa botshelo jwa letsatsi le letsatsi — OpenAmer e tsaya tiro e go seng ope a e ratang.",
  u1t: "Tiro & ofisi",
  u1d: "Dikwalo tsa theko, dipego, diimeile le patlisiso ka metsotso go na le diura — ka go tsamaisana le go kwalwa sentle.",
  u2t: "Thuto & go ithuta",
  u2d: "Dikakaretso, dipego tsa thuto, tiro ya motswedi. Tlhaloganya go na le go kopa.",
  u3t: "Tlhabololo",
  u3d: "Kwala, sekaseka le go kwala khoutu. Dira diteko le go kgaola diboko ka tsamaiso.",
  u4t: "Letsatsi le letsatsi & thulaganyo",
  u4d: "Dikopano, ditaolo, dikonteraka, ipaakanyetso ya dikopano — o se ka wa lebala sepe gape.",
  faq_eyebrow: "Dipotso tse di botswang",
  faq_title: "Dipotso tse di botswang gantsi",
  q1: "Data ya me e nna kae?",
  a1: "Mo sedirisiweng sa gago. OpenAmer e boloka dipuisano, difaele le thulaganyo mo gae. Ga go dathabeisi e e mo gare le ga go fetisediwa kwa bathong ba bangwe ntle le fa o itlhophela go dirisa mofani wa leru.",
  q2: "A ke tlhoka khomputara e e maatla?",
  a2: "Nnyaa mo motlhankeding ka boeona. Mo dimelelong tsa gae go eletsega CPU ya seswa e e nang le 16 GB RAM kgotsa go feta; ka GPU e dira ka bonako thata.",
  q3: "A OpenAmer e mahala?",
  a3: "OpenAmer e motswedi o o bulegileng. Ga go ditshenyegelo tsa laesense. Ke dimelelo tsa leru fela tse di nang le ditshenyegelo tsa tiriso.",
  q4: "A nka oketsa bokgoni jwa me?",
  a4: "Ee. Dikgono di go letla go tlhalosa ditsamaiso tse di boelediwang e le dimojule. Fa di setse di kwadilwe, di nna teng mo sesheneng sengwe le sengwe.",
  q5: "A OpenAmer e emela ngaka kgotsa mmueledi?",
  a5: "Nnyaa. OpenAmer e tshegetsa patlisiso, thulaganyo le mokwalo — mme ga e emele kgakololo ya setegeniki.",
  q6: "Ke simolola jang?",
  a6: "Latela dikwalo mo GitHub. O tla bona dikgato tsa go tsenya tsa Windows, macOS, Linux le Android.",
  cta_title: "O ipaakanyeditse motlha o mosha?",
  cta_sub: "Tsenya OpenAmer mme o neele tiro e e utswang nako ya gago.",
  cta_b1: "Tsenya jaanong",
  cta_b2: "Bogela bidiyo",
  foot_desc: "Motlhankedi wa gago wa AI. Wa gae, wa sephiri le wa boammaaruri — o agilwe kwa Switzerland.",
  foot_product: "Sekumo",
  foot_res: "Ditswammung",
  foot_legal: "Semolao",
