  q2: "Menga kuchli kompyuter kerakmi?",
  a2: "Yordamchining o'zi uchun emas. Mahalliy modellar uchun kamida 16 GB RAM'li zamonaviy CPU tavsiya etiladi; GPU bilan u ancha tez ishlaydi.",
  q3: "OpenAmer bepulmi?",
  a3: "OpenAmer ochiq kodli. Litsenziya xarajatlari yo'q. Faqat bulut modellari foydalanishga asoslangan xarajatlarni keltirib chiqaradi.",
  q4: "O'z imkoniyatlarimni qo'sha olamanmi?",
  a4: "Ha. Ko'nikmalar takrorlanuvchi ish jarayonlarini modul sifatida belgilashga imkon beradi. Bir marta yozilgach, ular har bir sessiyada mavjud bo'ladi.",
  q5: "OpenAmer shifokor yoki advokatni almashtiradimi?",
  a5: "Yo'q. OpenAmer tadqiqot, tuzilma va so'z shakllantirishda yordam beradi — lekin professional maslahatni almashtirmaydi.",
  q6: "Qanday boshlayman?",
  a6: "GitHub'dagi hujjatlarga amal qiling. Windows, macOS, Linux va Android uchun o'rnatish qadamlarini topasiz.",
